/* From Uiverse.io by G4b413l - Tags: input */
.__UIV_SCOPE__ .group {
 position: relative;
}

.__UIV_SCOPE__ .input {
 font-size: 16px;
 padding: 10px 10px 10px 5px;
 display: block;
 width: 200px;
 border: none;
 border-bottom: 1px solid #515151;
 background: transparent;
}

.__UIV_SCOPE__ .input:focus {
 outline: none;
}

.__UIV_SCOPE__ label {
 color: #999;
 font-size: 18px;
 font-weight: normal;
 position: absolute;
 pointer-events: none;
 left: 5px;
 top: 10px;
 transition: 0.2s ease all;
 -moz-transition: 0.2s ease all;
 -webkit-transition: 0.2s ease all;
}

.__UIV_SCOPE__ .input:focus ~ label, .__UIV_SCOPE__ .input:valid ~ label {
 top: -20px;
 font-size: 14px;
 color: #5264AE;
}

.__UIV_SCOPE__ .bar {
 position: relative;
 display: block;
 width: 200px;
}

.__UIV_SCOPE__ .bar:before, .__UIV_SCOPE__ .bar:after {
 content: '';
 height: 2px;
 width: 0;
 bottom: 1px;
 position: absolute;
 background: #5264AE;
 transition: 0.2s ease all;
 -moz-transition: 0.2s ease all;
 -webkit-transition: 0.2s ease all;
}

.__UIV_SCOPE__ .bar:before {
 left: 50%;
}

.__UIV_SCOPE__ .bar:after {
 right: 50%;
}

.__UIV_SCOPE__ .input:focus ~ .bar:before, .__UIV_SCOPE__ .input:focus ~ .bar:after {
 width: 50%;
}

.__UIV_SCOPE__ .highlight {
 position: absolute;
 height: 60%;
 width: 100px;
 top: 25%;
 left: 0;
 pointer-events: none;
 opacity: 0.5;
}

.__UIV_SCOPE__ .input:focus ~ .highlight {
 animation: inputHighlighter 0.3s ease;
}

@keyframes inputHighlighter {
 from {
  background: #5264AE;
 }

 to {
  width: 0;
  background: transparent;
 }
}
